const D = { stacks: 2, scale: 1, hue: 210, energy: .6, punch: .7, speed: 1, density: .5, x: .5, y: .96, style: 'monolith', act: 'steady', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;

const STY = {
  monolith: { wire:false, cab:[220,12,10], bev:[220,10,20], edge:[210,8,42], grill:[220,8,6],  cone:[30,8,26],  cap:[35,10,60], glow:[195,80,100], led:[120,80,100], wood:0 },
  vintage:  { wire:false, cab:[28,45,34],  bev:[28,52,46],  edge:[30,40,58],  grill:[32,30,20], cone:[34,26,70], cap:[36,30,86], glow:[40,70,100],  led:[45,80,100],  wood:1 },
  wireframe:{ wire:true,  cab:[190,60,50], bev:[190,50,70], edge:[190,70,92], grill:[190,40,30],cone:[190,50,60], cap:[190,40,90], glow:[190,70,100], led:[190,80,100], wood:0 },
  neon:     { wire:false, cab:[260,40,8],  bev:[280,60,30],  edge:[300,80,100],grill:[260,30,6], cone:[300,50,30], cap:[310,60,80], glow:[315,90,100], led:[135,90,100], wood:0 },
  riso:     { wire:false, cab:[220,55,60], bev:[350,60,66],  edge:[350,65,84], grill:[220,50,40],cone:[350,55,72], cap:[45,60,90],  glow:[350,70,100], led:[190,70,100], wood:0 }
};
const st = STY[P.style] || STY.monolith;
const ho = P.hue - 210;
const sh = c => [hw(c[0] + ho*0.35), c[1], c[2]];

const sec = ((Math.floor(K.section) % 8) + 8) % 8;
const arc = [.3,.5,.7,.9,.4,.7,1,.5][sec];
const ACT = {
  steady: { amp: .8,  rattle: 0.25, sub: .8 },
  build:  { amp: .5 + arc*.9, rattle: arc*0.7, sub: .6 + arc*.6 },
  wobble: { amp: 1,  rattle: .5, sub: 1, wob: 1 }
};
const act = ACT[P.act] || ACT.steady;

const nStacks = Math.max(1, Math.min(4, Math.round(P.stacks)));
const cw = u * (0.15 * P.scale);
const baseY = P.y * height;

// ---- build layout + static cabinet cache ----
const key = width+'x'+height+'|'+nStacks+'|'+P.style+'|'+P.seed+'|'+Math.round(P.scale*40)+'|'+Math.round(P.x*40)+'|'+Math.round(P.y*40)+'|'+Math.round(ho);
if (!S.bg || S.key !== key) {
  if (!S.bg) S.bg = createGraphics(width, height); else S.bg.resizeCanvas(width, height);
  const g = S.bg; g.clear(); g.colorMode(g.HSB, 360, 100, 100, 100);
  const cab = sh(st.cab), bev = sh(st.bev), edge = sh(st.edge), grill = sh(st.grill);
  const cones = [];
  const spanTotal = nStacks * cw + (nStacks-1) * cw*0.18;
  const startX = P.x*width - spanTotal/2 + cw/2;
  for (let s = 0; s < nStacks; s++) {
    const sx = startX + s * (cw + cw*0.18);
    // stack = sub box (bottom) + top box (2 mids + horn)
    const subH = cw * 1.02, topH = cw * 0.92;
    const subY = baseY - subH, topY = subY - topH - cw*0.03;
    // draw a cabinet box helper inline
    const drawBox = (bx, by, bw, bh) => {
      if (st.wire) {
        g.noFill(); g.stroke(edge[0],edge[1],edge[2],85); g.strokeWeight(Math.max(1.2,u*0.0018));
        g.rect(bx, by, bw, bh, bw*0.04);
        g.line(bx, by+bh*0.5, bx+bw, by+bh*0.5);
        return;
      }
      // body
      g.noStroke(); g.fill(cab[0],cab[1],cab[2]); g.rect(bx, by, bw, bh, bw*0.03);
      // raking shadow (right/bottom dark, top-left light)
      g.fill(cab[0],cab[1],Math.max(0,cab[2]-6), 60); g.rect(bx+bw*0.62, by, bw*0.38, bh, bw*0.03);
      g.fill(bev[0],bev[1],Math.min(100,bev[2]), 55); g.rect(bx, by, bw*0.05, bh);
      g.fill(bev[0],bev[1],Math.min(100,bev[2]+10), 45); g.rect(bx, by, bw, bh*0.04);
      // wood grain
      if (st.wood) { g.stroke(cab[0],cab[1]*0.7,cab[2]*0.7,22); g.strokeWeight(1);
        for (let w=0; w<8; w++){ const wy=by+bh*(w+0.5)/8; g.line(bx, wy+Math.sin(w)*2, bx+bw, wy-Math.sin(w*1.3)*2);} g.noStroke(); }
      // corner hardware
      g.fill(edge[0],edge[1],edge[2],70);
      [[bx+bw*0.06,by+bh*0.05],[bx+bw*0.94,by+bh*0.05],[bx+bw*0.06,by+bh*0.95],[bx+bw*0.94,by+bh*0.95]].forEach(p=>g.ellipse(p[0],p[1],bw*0.05,bw*0.05));
    };
    drawBox(sx - cw/2, subY, cw, subH);
    drawBox(sx - cw*0.44, topY, cw*0.88, topH);
    // grill dot texture on faces (static) — skip for wire
    if (!st.wire) {
      g.noStroke(); g.fill(grill[0],grill[1],grill[2],55);
      const gdo = cw*0.08;
      for (let gx = sx-cw*0.4; gx < sx+cw*0.4; gx += gdo)
        for (let gy = subY+cw*0.1; gy < subY+subH-cw*0.1; gy += gdo)
          g.ellipse(gx, gy, cw*0.02, cw*0.02);
    }
    // register cone centers (dynamic layers drawn each frame)
    cones.push({ x: sx, y: subY + subH*0.5, r: cw*0.38, kind:'sub' });
    cones.push({ x: sx - cw*0.2, y: topY + topH*0.32, r: cw*0.16, kind:'mid' });
    cones.push({ x: sx + cw*0.2, y: topY + topH*0.32, r: cw*0.16, kind:'mid' });
    cones.push({ x: sx, y: topY + topH*0.72, r: cw*0.1, kind:'horn' });
  }
  S.cones = cones;
  S.stacks = [];
  for (let s=0;s<nStacks;s++){ const sx = startX + s*(cw+cw*0.18); S.stacks.push({x:sx}); }
  S.key = key;
}
image(S.bg, 0, 0);

const cone = sh(st.cone), cap = sh(st.cap), glow = sh(st.glow), led = sh(st.led);

// ---- animated cones (pump) + bass halos ----
const cones = S.cones || [];
for (let i = 0; i < cones.length; i++) {
  const c = cones[i];
  let drive;
  if (c.kind === 'sub')  drive = (K.pulse*0.5 + K.swell*0.28) * act.sub + A.bass * 1.0;
  else if (c.kind === 'mid') drive = (K.pulse*0.32 + K.swell*0.2) + A.lowmid*0.7 + A.mid*0.5;
  else drive = (K.pulse*0.25) + A.treble*0.8;
  drive += 0.34*(0.5 + 0.5*Math.sin(K.t*1.7*P.speed + i*0.9));
  if (act.wob) drive *= 0.6 + 0.7*Math.abs(Math.sin(K.t*3.3 + i));
  const pump = Math.max(0, Math.min(1.4, drive * P.punch * (0.7 + P.energy*0.6)));
  // rattle jitter at peak
  const jx = act.rattle * pump * Math.sin(K.t*40 + i*7) * u*0.002;
  const jy = act.rattle * pump * Math.cos(K.t*37 + i*3) * u*0.002;
  const x = c.x + jx, y = c.y + jy, r = c.r;
  push();
  if (st.wire) {
    noFill(); stroke(cone[0],cone[1],cone[2],80); strokeWeight(Math.max(1,u*0.0014));
    for (let k=1;k<=3;k++) ellipse(x, y, r*2*(k/3)*(1-pump*0.12), r*2*(k/3)*(1-pump*0.12));
  } else {
    // surround
    noStroke(); fill(cone[0],cone[1]*0.7,cone[2]*0.7,90); ellipse(x, y, r*2.1, r*2.1);
    // cone body pushed in (darker toward center as it pumps)
    for (let k=4;k>=1;k--){ const t=k/4; const dim = 1 - pump*0.35*(1-t);
      fill(cone[0],cone[1],cone[2]*dim, 92); ellipse(x, y, r*2*t, r*2*t); }
    // dust cap highlight (scales with pump -> visible motion)
    fill(cap[0],cap[1],cap[2],95); ellipse(x - r*0.12, y - r*0.12, r*(0.5 - pump*0.16), r*(0.5 - pump*0.16));
  }
  // bass halo (additive, large area -> motion + energy)
  blendMode(ADD); noStroke();
  fill(glow[0], glow[1], glow[2], Math.min(34, 6 + pump*30));
  ellipse(x, y, r*(2.4 + pump*2.2), r*(2.4 + pump*2.2));
  blendMode(BLEND);
  pop();
}

// ---- sweeping stage light: real-time horizontal motion floor (never re-phases) ----
blendMode(ADD); noStroke();
{ const sweepSpan = width + u*0.5;
  const sx2 = ((K.t*u*0.075*P.speed) % sweepSpan + sweepSpan) % sweepSpan - u*0.25;
  const beamW = u*0.16, beamA = 7 + K.swell*5;
  for (let yy = 0; yy <= height; yy += u*0.12) {
    fill(glow[0], glow[1], glow[2], beamA);
    ellipse(sx2 + Math.sin(yy*0.01 + K.t)*u*0.012, yy, beamW, u*0.17);
  } }
blendMode(BLEND);
// ---- VU / LED bar on each stack (grill glow) ----
push();
const stk = S.stacks || [];
for (let s = 0; s < stk.length; s++) {
  const sx = stk[s].x;
  const barY = baseY - cw*0.06;
  const nLed = 7;
  const level = Math.min(1, K.intensity*0.4 + K.pulse*0.4 + A.rms*2.2 + 0.15*Math.sin(K.t*1.3+s));
  for (let l = 0; l < nLed; l++) {
    const lit = (l/nLed) < level;
    const lx = sx - cw*0.32 + (l/(nLed-1))*cw*0.64;
    const lh = l/nLed;
    const lc = lh < 0.6 ? led : (lh < 0.85 ? [45,90,100] : [0,85,100]);
    if (lit) { blendMode(ADD); noStroke(); fill(lc[0],lc[1],lc[2], 55); ellipse(lx, barY, cw*0.06, cw*0.04); blendMode(BLEND);
      fill(lc[0],lc[1]*0.8,100,95); ellipse(lx, barY, cw*0.03, cw*0.02); }
    else { noStroke(); fill(lc[0],lc[1]*0.5,lc[2]*0.2, 70); ellipse(lx, barY, cw*0.028, cw*0.018); }
  }
}
pop();

blendMode(BLEND);
if (drawingContext) drawingContext.shadowBlur = 0;
